// ============================================================================
// companyHeaderConfig.js
// ----------------------------------------------------------------------------
// المصدر الموحّد الوحيد (Single Source of Truth) للهوية الرسمية لشركة MSCANCO.
//
// أي نص أو صورة أو لون يخص هيدر الشركة يجب أن يُقرأ من هذا الملف فقط، ولا
// يجوز تكراره أو كتابته يدويًا في أي ملف تاني بالمشروع (HTML / PDF / Excel /
// الطباعة المباشرة). أي تعديل مستقبلي على الهوية (نص، شعار، شهادات) يتم هنا
// مرة واحدة فقط وينعكس تلقائيًا على كل التقارير والواجهات.
//
// لماذا Base64 مباشرة بدل fetch() لملف صورة؟
// ----------------------------------------------------------------------------
// النسخة القديمة (branding.js) كانت بتحمّل شعار الشركة عبر fetch() لملف PNG
// فعلي وتحوّله لـ Data URL وقت التشغيل (Runtime) وتخزّنه في متغيّر Cache. ده
// كان بيشتغل غالبًا بس بيفتح احتمال فشل حقيقي في حالات:
//   • أول تحميل للتطبيق قبل ما الـ Service Worker يخلّص تسجيل نفسه وتخزين
//     الأصول (خصوصًا على شبكة بطيئة/غير مستقرة في المصنع).
//   • فتح تقرير PDF/Excel بسرعة قبل ما وعد (Promise) التحميل يخلّص.
//   • أي بيئة تصفح بتمنع fetch() لملفات محلية (file://) بدون سيرفر.
//
// الحل الجذري هنا: الصور نفسها مُضمَّنة (Embedded) كسلاسل Base64 داخل كود
// الـ JS ذاته. الملف ده بقى "الأصل" الحقيقي، ومفيش أي انتظار أو طلب شبكة أو
// حتى قراءة من القرص مطلوبة عشان الهيدر يظهر - الصورة موجودة فعليًا في نفس
// اللحظة اللي بيتحمّل فيها الملف. ده أقوى ضمان ممكن لعمل الهيدر Offline 100%
// من أول Byte، حتى قبل أي Service Worker أو Cache.
//
// ملحوظة: الصور الأصلية اتضغطت (PNG Palette Quantization، بدون أي فقدان
// ملحوظ في الجودة البصرية) عشان سلاسل الـ Base64 تفضل بحجم معقول جوه كود
// الـ JS. الملفات الأصلية لسه موجودة في assets/branding/ برضه كنسخة احتياطية
// وكـ fallback اختياري (مسارات LOGO_MAIN_PATH إلخ بالأسفل) في حالة احتجت
// تستخدمها مباشرة في أي مكان آخر.
// ============================================================================

// ------------------------------------------------------------
// 1. النصوص الرسمية
// ------------------------------------------------------------
export const COMPANY_NAME_AR = "شركة محمود سعيد لصناعة علب المرطبات والأغطية المحدودة";
export const COMPANY_NAME_EN = "MAHMOOD SAEED BEVERAGE CANS & ENDS INDUSTRY COMPANY LTD.";
export const COMPANY_SHORT   = "MSCANCO";

// ------------------------------------------------------------
// 2. شهادات الاعتماد الأربعة (SGS / ISO) - بيانات وصفية فقط
//    (الصورة المرئية للأختام الأربعة نفسها في CERT_BADGES_DATA_URL بالأسفل)
// ------------------------------------------------------------
export const CERTIFICATIONS = [
  { code: "FSSC 22000", nameAr: "سلامة الغذاء",              nameEn: "Food Safety Management" },
  { code: "ISO 9001",   nameAr: "إدارة الجودة",               nameEn: "Quality Management" },
  { code: "ISO 14001",  nameAr: "الإدارة البيئية",            nameEn: "Environmental Management" },
  { code: "ISO 45001",  nameAr: "السلامة والصحة المهنية",     nameEn: "Occupational Health & Safety" }
];

// ------------------------------------------------------------
// 3. لوحة الألوان الرسمية الموحّدة
//    (بصيغتين: HEX لاستخدام HTML/CSS، وARGB لاستخدام ExcelJS مباشرة)
// ------------------------------------------------------------
export const HEADER_COLORS = {
  navy:        "#0B3D91",
  navyArgb:    "FF0B3D91",
  dark:        "#1E293B",
  darkArgb:    "FF1E293B",
  lightGrey:   "#F1F5F9",
  lightGreyArgb: "FFF1F5F9",
  white:       "#FFFFFF",
  whiteArgb:   "FFFFFFFF",
  borderGrey:  "#E2E8F0",
  borderGreyArgb: "FFE2E8F0",
  accentGold:  "#F5A623"
};

// ------------------------------------------------------------
// 4. مسارات ملفات الصور الأصلية على القرص (Fallback / مرجع فقط)
// ------------------------------------------------------------
export const LOGO_MAIN_PATH    = "assets/branding/logo-main.png";           // الطرف الأيسر: شعار MSCANCO + الاسم المختصر
export const LOGO_ICON_PATH    = "assets/branding/logo-mark.png";           // الأيقونة الدائرية فقط (هيدر التطبيق العلوي المضغوط)
export const CERT_BADGES_PATH  = "assets/branding/certifications-badges.png"; // الطرف الأيمن: أختام SGS/ISO الأربعة مجمّعة
export const COMPANY_BANNER_PATH = "assets/branding/company-banner.png";    // البانر الكامل (الشعار + الاسم + الشهادات) كصورة واحدة

// ------------------------------------------------------------
// 5. الصور كـ Base64 Data URLs (المصدر الفعلي المستخدم في كل التقارير)
// ------------------------------------------------------------
const LOGO_MAIN_BASE64 = "";

const CERT_BADGES_BASE64 = "";

const LOGO_ICON_BASE64 = "";

const COMPANY_BANNER_BASE64 = "";

export const LOGO_MAIN_DATA_URL      = `data:image/png;base64,${LOGO_MAIN_BASE64}`;
export const CERT_BADGES_DATA_URL    = `data:image/png;base64,${CERT_BADGES_BASE64}`;
export const LOGO_ICON_DATA_URL      = `data:image/png;base64,${LOGO_ICON_BASE64}`;
export const COMPANY_BANNER_DATA_URL = `data:image/png;base64,${COMPANY_BANNER_BASE64}`;

// ------------------------------------------------------------
// 6. دوال وصول موحّدة (استخدمها بدل ما تكتب أسماء المتغيرات مباشرة)
// ------------------------------------------------------------

/**
 * يرجع كل أصول هيدر الشركة دفعة واحدة (نصوص + صور Base64 + ألوان).
 * أي مكوّن (HTML / PDF / Excel) لازم ياخد بياناته من هنا فقط.
 */
export function getCompanyHeaderAssets() {
  return {
    companyNameAr: COMPANY_NAME_AR,
    companyNameEn: COMPANY_NAME_EN,
    companyShort: COMPANY_SHORT,
    certifications: CERTIFICATIONS,
    colors: HEADER_COLORS,
    logoMain: LOGO_MAIN_DATA_URL,
    logoIcon: LOGO_ICON_DATA_URL,
    certBadges: CERT_BADGES_DATA_URL,
    banner: COMPANY_BANNER_DATA_URL
  };
}

/**
 * إبقاء نفس التوقيع القديم (Promise) المستخدم في باقي المشروع لتوافقية كاملة
 * مع الكود الحالي (exportUtility.js وغيره بيعمل await على الدالة دي) - لكن
 * دلوقتي بترجع فورًا (Resolve مباشر) من غير أي fetch أو انتظار شبكة، لأن
 * الصورة أصلاً Base64 مُضمّنة جوه الملف ده. البانر الكامل هو المستخدم في
 * هيدر PDF/Excel المُصدَّر لأنه يحتوي الشعار + الاسم + الشهادات في صورة واحدة
 * جاهزة للطباعة المباشرة بأعلى دقة ممكنة.
 */
export function getCompanyLogoDataUrl() {
  return Promise.resolve(COMPANY_BANNER_DATA_URL);
}
